// THE PLAYERS' PAGE (build 2026-11-11b; tools/bundle.js). The owner, 2026-11-11: "the page loads 96 separate scripts, 3.3 megabytes on an iPad over the network. A single bundled file at deploy time
// would load faster. We can work on that, right?"
//   FRESH       dist/conduit.js and play.html are what tools/bundle.js makes from game.html and js/*.js now (node tools/stamp.js makes them for every build; a stale one fails here)
//   THE PAGE    play.html is game.html with its scripts before the boot check replaced by the one file; the boot check and js/init.js as they were; the website links to it
//   THE WAY IN  over the web game.html sends a visitor to play.html (not with ?dev, nor ?attract, nor off the web)
//   THE SAME    in a real browser play.html starts with no error, and every top-level name the scripts declare is the same kind of thing as in game.html (one file is not many: a name a later
//               file declares could be read too early by an earlier one; it is not)
const fs = require('fs'), path = require('path'), os = require('os');
const { execFileSync } = require('child_process');
const ROOT = path.join(__dirname, '..');
const rd = f => fs.readFileSync(path.join(ROOT, f), 'utf8');
const B = require(path.join(ROOT, 'tools/bundle.js'));
let failures = 0;
function group(n) { console.log('\n' + n); }
function check(name, fn) { try { fn(); console.log('  ok   ' + name); } catch (e) { failures++; console.log('  FAIL ' + name + ' — ' + e.message); } }
function ok(c, m) { if (!c) throw new Error(m); }
function same(a, b, m) { if (a !== b) throw new Error(`${m}: expected ${JSON.stringify(b)}, got ${JSON.stringify(a)}`); }
function findChromium() {
    const fromEnv = process.env.CHROMIUM_PATH; if (fromEnv && fs.existsSync(fromEnv)) return fromEnv;
    const base = process.env.PLAYWRIGHT_BROWSERS_PATH || '/opt/pw-browsers'; let dirs = [];
    try { dirs = fs.readdirSync(base); } catch (e) { return null; }
    for (const d of dirs.filter(d => d.startsWith('chromium')).sort().reverse()) for (const rel of ['chrome-headless-shell-linux64/chrome-headless-shell', 'chrome-linux/headless_shell', 'chrome-linux/chrome', 'chrome-linux64/chrome']) { const p = path.join(base, d, rel); if (fs.existsSync(p)) return p; }
    for (const p of ['/usr/bin/chromium', '/usr/bin/chromium-browser', '/usr/bin/google-chrome']) if (fs.existsSync(p)) return p;
    return null;
}

group('FRESH (tools/bundle.js)');
let made = null;
check('dist/conduit.js and play.html are what tools/bundle.js makes from game.html and js/*.js now (else: node tools/bundle.js, or stamp the build)', () => {
    made = B.build();
    ok(fs.existsSync(path.join(ROOT, 'dist/conduit.js')) && fs.existsSync(path.join(ROOT, 'play.html')), 'dist/conduit.js or play.html is missing');
    ok(rd('dist/conduit.js') === made.js, 'dist/conduit.js is stale: node tools/bundle.js'); ok(rd('play.html') === made.play, 'play.html is stale: node tools/bundle.js');
    same(made.build, (rd('js/config.js').match(/const BUILD_VERSION = "([^"]+)"/) || [])[1], 'the build it names');
});

group('THE PAGE (play.html)');
check('play.html loads the one file and then js/init.js, with the boot check between them as in game.html, and says it is made, not written', () => {
    const p = rd('play.html'), tags = [...p.matchAll(/<script src="([^"?]+)\?v=([^"]*)"><\/script>/g)].map(m => m[1]);
    same(tags.join(), 'dist/conduit.js,js/init.js', 'its scripts'); ok(/BOOT CHECK/.test(p.slice(p.indexOf('<script src="dist/conduit.js'), p.indexOf('<script src="js/init.js'))), 'no boot check between them');
    ok(/GENERATED by tools\/bundle\.js from game\.html/.test(p), 'no note that it is made');
});
check('the one file holds every script game.html loads before its boot check, in that order, without its comments and without strict mode', () => {
    const want = B.sources(rd('game.html')).bundled.map(t => t.file), js = rd('dist/conduit.js'), got = [...js.matchAll(/^\/\* (js\/[^ ]+) \*\/$/gm)].map(m => m[1]);
    same(got.join(), want.join(), 'its scripts and their order'); same(want.length, rd('game.html').split('\n').filter(l => /<script src="js\//.test(l)).length - 1, 'every script but js/init.js');
    ok(!/^\s*["']use strict["']/m.test(js), 'strict mode was added'); ok(js.length < want.reduce((n, f) => n + rd(f).length, 0) * 0.9, 'the comments were not taken out');
});
check('the website links to play.html, and its background is play.html?attract', () => { const h = rd('index.html'); ok(/href="play\.html"/.test(h), 'the link'); ok(/frame\.src = 'play\.html\?attract'/.test(h), 'the background'); });

group('THE WAY IN (game.html\'s head)');
check('over the web, game.html sends a visitor to play.html, keeping what follows the address; not with ?dev or ?attract, not off the web, and play.html never sends anyone on', () => {
    const line = (rd('game.html').match(/\n    (if \(location\.protocol === "https:" && [^\n]*location\.replace\([^\n]*\);)/) || [])[1]; ok(line, 'no way in in game.html\'s head');
    const go = (protocol, pathname, search, hash) => { let to = null; new Function('location', line)({ protocol, pathname, search: search || '', hash: hash || '', replace: u => { to = u; } }); return to; };
    same(go('https:', '/Conduit/game.html'), '/Conduit/play.html', 'the live site'); same(go('https:', '/Conduit/game'), '/Conduit/play.html', 'without .html');
    same(go('https:', '/Conduit/game.html', '?power=on', '#boot1'), '/Conduit/play.html?power=on#boot1', 'what follows the address');
    same(go('https:', '/Conduit/game.html', '?dev'), null, '?dev'); same(go('https:', '/Conduit/game.html', '?attract'), null, '?attract');
    same(go('http:', '/game.html'), null, 'a local server'); same(go('file:', '/home/user/Conduit/game.html'), null, 'a file'); same(go('https:', '/Conduit/play.html'), null, 'play.html itself');
});

group('THE SAME (real browser)');
const names = new Set(); for (const f of B.sources(rd('game.html')).bundled.map(t => t.file)) for (const m of rd(f).matchAll(/^(?:async\s+)?(?:function\s*\*?\s*(\w+)|(?:const|let|var|class)\s+(\w+))/gm)) names.add(m[1] || m[2]);
function page(file) {
    const bin = findChromium(); if (!bin) return null;
    const SCRIPT = `<script>window.addEventListener('load', function(){ setTimeout(function(){ var N = ${JSON.stringify([...names])}, t = {};
      for (var i = 0; i < N.length; i++) { try { t[N[i]] = (0, eval)('typeof ' + N[i]); } catch (e) { t[N[i]] = 'ERR'; } }
      var out = { state: typeof STARTUP !== 'undefined' ? STARTUP.state : null, broken: !!window.__bootBroken, failed: (window.__bootFailed || []).slice(), errors: (window.__pageErrors || []).slice(), types: t };
      var pre = document.createElement('pre'); pre.id = '__bd'; pre.textContent = JSON.stringify(out); document.body.appendChild(pre); }, 3000); });</script></body>`;
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'bd-')), tmp = path.join(dir, file);
    fs.writeFileSync(tmp, rd(file).replace(/<head>/i, '<head><base href="file://' + ROOT + '/"><script>window.__pageErrors = []; window.addEventListener("error", function (e) { window.__pageErrors.push(String(e.message || e)); });</script>').replace(/<\/body>/i, () => SCRIPT));
    let dom = '';
    try { dom = execFileSync(bin, ['--headless=new', '--no-sandbox', '--disable-gpu', '--allow-file-access-from-files', '--window-size=1180,820', '--virtual-time-budget=20000', '--dump-dom', 'file://' + tmp], { encoding: 'utf8', maxBuffer: 64 * 1024 * 1024, timeout: 120000, stdio: ['ignore', 'pipe', 'ignore'] }); } catch (e) { dom = (e && e.stdout) || ''; }
    try { fs.rmSync(dir, { recursive: true, force: true }); } catch (e) {}
    const m = dom.match(/<pre id="__bd">([\s\S]*?)<\/pre>/); return m ? JSON.parse(m[1].replace(/&quot;/g, '"').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')) : undefined;
}
const G = page('game.html'), P = G === null ? null : page('play.html');
if (G === null) console.log('  (no Chromium here: skipped)');
else {
    check('play.html starts: no error, nothing missing at the boot check, the start done (as game.html)', () => {
        ok(P, 'play.html produced nothing'); ok(G, 'game.html produced nothing');
        for (const [k, r] of [['game.html', G], ['play.html', P]]) { same(r.errors.join(' | '), '', k + ': errors'); same(r.broken, false, k + ': the boot check broke'); same(r.failed.join(), '', k + ': files that failed'); same(r.state, 'done', k + ': the start'); }
    });
    check('every top-level name the ' + names.size + ' declarations make is the same kind of thing in play.html as in game.html (none read too early, none lost)', () => {
        const diff = [...names].filter(k => G.types[k] !== P.types[k]); same(diff.length, 0, 'names that differ: ' + diff.slice(0, 8).map(k => k + ' ' + G.types[k] + '/' + P.types[k]).join(', '));
        ok(Object.values(P.types).filter(v => v === 'undefined').length < names.size / 10, 'most names are missing in both');
    });
}
console.log(failures ? `\n${failures} FAILING\n` : '\nall passing\n');
process.exit(failures ? 1 : 0);
